target.css:
:root {
  --ink: #173c4d;
  --muted: #5d7480;
  --paper: #fffdf7;
  --line: #c8dce0;
  --aqua: #d9f2ef;
  --deep-aqua: #177e89;
  --coral: #f27d67;
  --soft-coral: #fff0ea;
}

.swim-pass {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.pass-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid var(--line);
}

.venue {
  display: flex;
  align-items: center;
  gap: 10px;
}

.wave {
  display: grid;
  width: 31px;
  height: 31px;
  place-items: center;
  color: var(--paper);
  background: var(--deep-aqua);
  border-radius: 50%;
  font-size: 23px;
  font-weight: 700;
  line-height: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.status {
  padding: 5px 9px;
  color: var(--deep-aqua);
  background: var(--aqua);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.reservation {
  display: grid;
  grid-template-columns: 104px 1fr;
  gap: 16px;
  padding: 16px 18px;
}

.date-tile {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 106px;
  color: var(--ink);
  background: var(--soft-coral);
  border: 1px solid var(--coral);
  border-radius: 12px;
  line-height: 1.1;
}

.month {
  color: var(--coral);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.date-tile strong {
  margin: 3px 0;
  font-size: 37px;
  line-height: 1;
}

.date-tile span:last-child {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.session h1 {
  margin: 1px 0 4px;
  font-size: 20px;
  line-height: 1.2;
}

.session > p {
  margin: 0 0 11px;
  color: var(--muted);
  font-size: 13px;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.details li {
  color: var(--ink);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.35;
}

.details span {
  display: block;
  margin-bottom: 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  background: var(--aqua);
}

.code {
  color: var(--muted);
  font-size: 12px;
}

.code strong {
  color: var(--ink);
  letter-spacing: 0.06em;
}

button {
  padding: 7px 11px;
  color: var(--paper);
  background: var(--deep-aqua);
  border: 0;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

